class Solution {
public:
    vector<long long> sumOfThree(long long num) {
        if (num % 3 != 0) return {};
        long long mid = num / 3;
        return {mid - 1, mid, mid + 1};
    }
};

class Solution {
    public long[] sumOfThree(long num) {
        if (num % 3 != 0) return new long[0];
        long mid = num / 3;
        return new long[]{mid - 1, mid, mid + 1};
    }
}

var sumOfThree = function(num) {
    const bNum = BigInt(num);
    if (bNum % 3n !== 0n) return [];
    const mid = bNum / 3n;
    return [Number(mid - 1n), Number(mid), Number(mid + 1n)];
};
